import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

// Story 14-S7 — Play, checked in the source.
//
// Play's screen, its controls and dialogs, the Prominent Hint and the
// Player Hints paint only through the redesign's tokens, and the play
// grid has no inset ring painted from old tokens. The rendered screen is
// checked in the browser by e2e/play-design.spec.ts. The confetti keeps
// its own colors (not part of this story).
// Do not edit this file to match an implementation.

const SRC = fileURLToPath(new URL('../../', import.meta.url));

const PLAY_FILES = [
  'app/puzzles/[id]/play/page.tsx',
  'components/play/PlayPuzzle.tsx',
  'components/play/PlayReset.tsx',
  'components/play/PlayerHints.tsx',
  'components/play/ProminentHint.tsx',
];

function source(path: string) {
  return readFileSync(join(SRC, path), 'utf8');
}

function withoutComments(code: string) {
  return code.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/.*$/gm, '$1');
}

const OLD_COLOR_TOKENS = [
  'background',
  'foreground',
  'ink-2',
  'ink-3',
  'rule',
  'rule-strong',
  'hover-tint',
  'panel-tint',
  'accent',
  'accent-hover',
  'ok-tint',
  'required',
  'recommended',
  'incomplete',
];

function expectRedesignTokensOnly(code: string, label: string) {
  expect(code, label).not.toMatch(/#[0-9a-f]{3,8}\b/i);
  expect(code, label).not.toMatch(/\b(rgb|rgba|hsl|hsla|oklch)\(/);
  expect(code, label).not.toMatch(/\b(text|bg|border|fill|stroke)-(white|black)\b/);
  expect(code, label).not.toMatch(/\bring-/);
  expect(code, label).not.toMatch(/\brounded-(btn|sm|md|lg|grid)\b/);
  expect(code, label).not.toMatch(/\bshadow\b|\bshadow-/);
  expect(code, label).not.toMatch(/\bfont-display\b|\btext-(headline|body|help|xl|title)(?![\w-])/);
  expect(code, label).not.toMatch(/\btext-(xs|sm|base|lg|[2-9]xl)\b/);
  expect(code, label).not.toMatch(/\[font-weight:/);
  expect(code, label).not.toMatch(/--color-(?:ink-|accent|grid-line-)/);
  for (const name of OLD_COLOR_TOKENS) {
    expect(code, `${label}: ${name}`).not.toMatch(
      new RegExp(`(?:^|[\\s'"\`:])(?:text|bg|border|fill|stroke)-${name}(?![\\w-])`),
    );
  }
}

describe('14-S7 play source', () => {
  it('the play screen, its controls and dialogs, Prominent Hint and Player Hints use only the redesign tokens', () => {
    for (const path of PLAY_FILES) expectRedesignTokensOnly(withoutComments(source(path)), path);
  });

  it('the play grid draws its lines and selection from the play-cell styles, with no inset ring', () => {
    const grid = withoutComments(source('components/grid/PuzzleGrid.tsx'));
    expect(grid).not.toMatch(/grid-line-play/);
    expect(grid).not.toMatch(/boxShadow|box-shadow/);
    expect(grid).not.toMatch(/--color-(?:accent|ink-3)/);
    for (const style of [
      'play-cell-on',
      'play-cell-off',
      'play-cell-border',
      'play-cell-selected-cell',
      'play-cell-selected-row',
    ]) {
      expect(grid, style).toMatch(new RegExp(`\\bbg-${style}\\b`));
    }
  });
});
